<script setup lang="ts">
import { computed, reactive, ref } from 'vue'

type ProxyStatus = 'active' | 'pending' | 'off' | 'testing'
type ProxyRow = { id: string; name: string; protocol: string; host: string; port: string; region: string; latency: string; expiry: string; status: ProxyStatus; refs: string[]; tag: string; tested: string; exitIp?: string; probeTarget?: string; probeVersion?: string }

const rows = ref<ProxyRow[]>([
  { id: 'proxy_01HOMNI', name: 'Google Omni 出口', protocol: 'HTTP', host: 'proxy-us.example.net', port: '8080', region: '美国 · 洛杉矶', latency: '142 ms', expiry: '2027-03-12', status: 'active', refs: ['Video MCP / Google Omni · 渠道 01', 'Video MCP / Google Omni · 渠道 02'], tag: 'google, primary', tested: '2 分钟前', exitIp: '198.51.100.24', probeTarget: 'egress_probe · ipify', probeVersion: 'probe-2026.09' },
  { id: 'proxy_01IMGCDN', name: 'Image CDN', protocol: 'SOCKS5H', host: 'proxy-sg.example.net', port: '7891', region: '新加坡', latency: '188 ms', expiry: '2026-12-31', status: 'active', refs: ['Image MCP / Image CDN · 主出口'], tag: 'image', tested: '18 分钟前', exitIp: '203.0.113.18', probeTarget: 'egress_probe · ipify', probeVersion: 'probe-2026.09' },
  { id: 'proxy_01MUSIC', name: 'Music Provider', protocol: 'HTTPS', host: 'proxy-jp.example.net', port: '443', region: '日本 · 东京', latency: '—', expiry: '长期有效', status: 'pending', refs: [], tag: 'music', tested: '尚未测试' },
  { id: 'proxy_01BACKUP', name: '备用出口', protocol: 'SOCKS5', host: 'proxy-hk.example.net', port: '1080', region: '香港', latency: '—', expiry: '2026-09-01', status: 'off', refs: [], tag: 'backup', tested: '2026-08-20' },
])

const query = ref('')
const protocol = ref('')
const status = ref('')
const binding = ref('')
const selected = ref<string[]>([])
const drawer = ref<ProxyRow | null>(null)
const modal = ref<'add' | 'edit' | 'import' | 'delete' | null>(null)
const editingId = ref<string | null>(null)
const deleteIds = ref<string[]>([])
const notice = ref('')
const importText = ref('')
const importPreview = ref('')
const form = reactive({ name: '', protocol: 'HTTP', host: '', port: '', region: '', expiry: '长期有效', tag: '', username: '', password: '', note: '' })

const statusText: Record<ProxyStatus, string> = { active: '正常', pending: '待测试', off: '已停用', testing: '测试中' }
const probeFixtures: Record<string, { latency: string; ip: string; region: string }> = { proxy_01HOMNI: { latency: '142 ms', ip: '198.51.100.24', region: '美国 · 洛杉矶' }, proxy_01IMGCDN: { latency: '188 ms', ip: '203.0.113.18', region: '新加坡' }, proxy_01MUSIC: { latency: '241 ms', ip: '192.0.2.44', region: '日本 · 东京' }, proxy_01BACKUP: { latency: '—', ip: '', region: '香港' } }
const filtered = computed(() => rows.value.filter((row) => {
  const needle = query.value.trim().toLowerCase()
  return (!needle || `${row.name} ${row.host} ${row.tag}`.toLowerCase().includes(needle)) && (!protocol.value || row.protocol === protocol.value) && (!status.value || row.status === status.value) && (!binding.value || binding.value === 'bound' ? row.refs.length > 0 : binding.value === 'unbound' ? row.refs.length === 0 : true)
}))
const activeCount = computed(() => rows.value.filter((row) => row.status === 'active').length)
const pendingCount = computed(() => rows.value.filter((row) => row.status === 'pending').length)
const referenceCount = computed(() => rows.value.reduce((total, row) => total + row.refs.length, 0))
const allSelected = computed(() => filtered.value.length > 0 && filtered.value.every((row) => selected.value.includes(row.id)))

function flash(message: string) { notice.value = message; window.setTimeout(() => { notice.value = '' }, 2600) }
function resetForm(row?: ProxyRow) { Object.assign(form, row ? { ...row, username: '', password: '', note: '' } : { name: '', protocol: 'HTTP', host: '', port: '', region: '', expiry: '长期有效', tag: '', username: '', password: '', note: '' }) }
function openAdd() { editingId.value = null; resetForm(); modal.value = 'add' }
function openEdit(row: ProxyRow) { editingId.value = row.id; resetForm(row); drawer.value = null; modal.value = 'edit' }
function save() {
  if (!form.name || !form.host || !form.port) return
  if (editingId.value) {
    const row = rows.value.find((item) => item.id === editingId.value)
    if (row) Object.assign(row, { ...form, status: 'pending', latency: '—', tested: '尚未测试', exitIp: '', probeTarget: '', probeVersion: '' })
    flash('代理已保存，等待重新测试')
  } else {
    rows.value.unshift({ id: `proxy_${Math.random().toString(36).slice(2, 9).toUpperCase()}`, name: form.name, protocol: form.protocol, host: form.host, port: form.port, region: form.region || '未探测', latency: '—', expiry: form.expiry, status: 'pending', refs: [], tag: form.tag || 'untagged', tested: '尚未测试', exitIp: '', probeTarget: '', probeVersion: '' })
    flash('代理已保存，待连接测试')
  }
  modal.value = null
}
function test(row: ProxyRow) {
  if (row.status === 'testing') return
  row.status = 'testing'; flash(`正在探测 ${row.name}…`)
  window.setTimeout(() => { const fixture = probeFixtures[row.id] ?? { latency: '203 ms', ip: '192.0.2.88', region: row.region }; row.status = 'active'; row.latency = fixture.latency; row.exitIp = fixture.ip; row.region = fixture.region; row.probeTarget = 'egress_probe · ipify'; row.probeVersion = 'probe-2026.09'; row.tested = '刚刚'; flash(`${row.name} Core 探测通过，出口 ${row.exitIp || '未返回'}`) }, 900)
}
function toggle(row: ProxyRow) { row.status = row.status === 'off' ? 'pending' : 'off'; flash(row.status === 'off' ? '代理已停用' : '代理已启用') }
function askDelete(rowsToDelete: ProxyRow[]) { if (rowsToDelete.some((row) => row.refs.length)) { flash('已被渠道引用，不能直接删除；请先解除引用或停用'); return } deleteIds.value = rowsToDelete.map((row) => row.id); editingId.value = deleteIds.value[0] ?? null; modal.value = 'delete' }
function confirmDelete() { rows.value = rows.value.filter((row) => !deleteIds.value.includes(row.id)); selected.value = selected.value.filter((id) => !deleteIds.value.includes(id)); deleteIds.value = []; modal.value = null; drawer.value = null; flash('代理已删除') }
function toggleAll() { selected.value = allSelected.value ? selected.value.filter((id) => !filtered.value.some((row) => row.id === id)) : [...new Set([...selected.value, ...filtered.value.map((row) => row.id)])] }
function batchTest() { selected.value.map((id) => rows.value.find((row) => row.id === id)).filter(Boolean).forEach((row) => test(row as ProxyRow)) }
function parseImport() { const lines = importText.value.split('\n').map((line) => line.trim()).filter(Boolean); const valid = lines.filter((line) => /^(https?|socks5h?):\/\/.*:\d+$/.test(line)).length; importPreview.value = `解析结果：${valid} 条有效，${lines.length - valid} 条需检查，0 条重复` }
function confirmImport() { modal.value = null; importText.value = ''; importPreview.value = ''; flash('已导入代理，待测试') }
</script>

<template>
  <div class="proxy-page">
    <aside class="proxy-side">
      <a class="proxy-brand" href="#/market"><span class="proxy-mark">✦</span><span><b>VerdantFlare</b><small>STUDIO</small></span></a>
      <p class="side-label">工作台</p>
      <nav><a href="#/market">⌂ <span>总览</span></a><a href="#/market">✦ <span>应用市场</span></a><a class="selected" href="#/station/proxies">⌁ <span>Station</span></a><a href="#/market">◌ <span>审计日志</span></a></nav>
      <div class="proxy-user"><strong>YL</strong><span>Yuki Lin<small>Station 管理员</small></span></div>
    </aside>
    <main class="proxy-main">
      <header class="proxy-top"><div class="crumb"><span>Station</span><i>/</i><span>网络出口</span><i>/</i><b>代理管理</b></div><div class="top-right"><select><option>VF Production · cn-sh</option><option>VF Staging · cn-hz</option></select><span class="online"><i></i>在线</span><button aria-label="帮助">?</button></div></header>
      <section class="proxy-content">
        <div class="review-note"><i></i><b>开发预览</b> 示例数据 · Proxy API 接入后由 Station Core 提供事实数据</div>
        <div class="proxy-heading"><div><small>STATION CORE · EGRESS</small><h1>代理管理</h1><p>维护网络出口，为 Video、Image 和 Music MCP 渠道提供可引用的代理。</p></div><div class="heading-actions"><button @click="modal = 'import'">⇧ 导入</button><button class="primary" @click="openAdd">＋ 添加代理</button></div></div>
        <div class="metrics"><article><span>代理总数</span><strong>{{ rows.length }}</strong><small>当前 Station</small></article><article><span>可用代理</span><strong>{{ activeCount }}</strong><small class="ok">↑ 可用状态</small></article><article><span>待处理</span><strong>{{ pendingCount }}</strong><small class="warn">需要连接测试</small></article><article><span>已绑定渠道</span><strong>{{ referenceCount }}</strong><small>Video / Image MCP</small></article><article><span>最近探测</span><strong class="time">2 分钟前</strong><small>2026-09-21 14:28</small></article></div>
        <div class="toolbar"><label class="search">⌕<input v-model="query" placeholder="搜索名称或地址…"></label><select v-model="protocol"><option value="">协议：全部</option><option>HTTP</option><option>HTTPS</option><option>SOCKS5</option><option>SOCKS5H</option></select><select v-model="status"><option value="">状态：全部</option><option value="active">正常</option><option value="pending">待测试</option><option value="off">已停用</option><option value="testing">测试中</option></select><select v-model="binding"><option value="">绑定：全部</option><option value="bound">已绑定</option><option value="unbound">未绑定</option></select><span class="grow"></span><button @click="flash('列表已刷新')">↻ 刷新</button><button :disabled="!selected.length" @click="batchTest">▷ 批量测试</button><button @click="flash('已生成脱敏导出文件（开发预览未下载）')">⇩ 导出</button></div>
        <div v-if="selected.length" class="selection"><b>{{ selected.length }}</b> 个代理已选择 <span class="grow"></span><button @click="batchTest">▷ 测试连接</button><button class="danger" @click="askDelete(rows.filter((row) => selected.includes(row.id)))">删除</button></div>
        <div class="table-card"><table><thead><tr><th><input type="checkbox" :checked="allSelected" @change="toggleAll"></th><th>名称 / 标签</th><th>协议</th><th>地址</th><th>出口位置</th><th>延迟</th><th>引用</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id" :class="{chosen: selected.includes(row.id)}"><td><input type="checkbox" :checked="selected.includes(row.id)" @change="selected.includes(row.id) ? selected = selected.filter((id) => id !== row.id) : selected.push(row.id)"></td><td><button class="name" @click="drawer = row">{{ row.name }}</button><small class="id">{{ row.id }} · {{ row.tag }}</small></td><td><span class="protocol">{{ row.protocol }}</span></td><td><code>{{ row.host }}:{{ row.port }}</code></td><td>{{ row.region }}</td><td :class="row.status === 'active' ? 'ok' : 'warn'">{{ row.latency }}</td><td>{{ row.refs.length }} 个渠道</td><td>{{ row.expiry }}</td><td><span :class="['status', row.status]"><i></i>{{ statusText[row.status] }}</span></td><td><button class="icon" @click="drawer = row">⌕</button><button class="icon" @click="openEdit(row)">✎</button><button class="icon" @click="row.refs.length ? (drawer = row) : askDelete([row])">{{ row.refs.length ? '⊙' : '⌫' }}</button></td></tr></tbody></table><div v-if="!filtered.length" class="empty"><b>没有匹配的代理</b><span>调整搜索或筛选条件，或者添加一个新的代理。</span><button @click="openAdd">＋ 添加代理</button></div><footer>显示 {{ filtered.length }} 个代理 <span>‹　<strong>1</strong>　›</span></footer></div>
      </section>
    </main>
    <div v-if="drawer" class="drawer-shade" @click="drawer = null"></div><aside v-if="drawer" class="proxy-drawer"><header><div><h2>{{ drawer.name }}</h2><small>{{ drawer.id }}</small></div><button @click="drawer = null">×</button></header><div class="drawer-body"><span :class="['status', drawer.status]"><i></i>{{ statusText[drawer.status] }}</span><section><h3>Core 代理探测</h3><p class="probe-explain">该结果来自 Station Core 经此代理访问固定探测目标，只证明代理出口可达，不代表供应商渠道已接入。</p><dl><div><dt>协议</dt><dd>{{ drawer.protocol }}</dd></div><div><dt>地址</dt><dd>{{ drawer.host }}:{{ drawer.port }}</dd></div><div><dt>观测出口 IP</dt><dd>{{ drawer.exitIp || '尚未探测' }}</dd></div><div><dt>出口位置</dt><dd>{{ drawer.region }}</dd></div><div><dt>探测目标 / 版本</dt><dd>{{ drawer.probeTarget || '—' }}<small v-if="drawer.probeVersion">{{ drawer.probeVersion }}</small></dd></div><div><dt>最近延迟</dt><dd>{{ drawer.latency }}</dd></div><div><dt>认证</dt><dd class="masked">●●●●●● 已配置</dd></div><div><dt>最近探测</dt><dd>{{ drawer.tested }}</dd></div></dl><div class="drawer-actions"><button @click="test(drawer)">▷ Core 探测</button></div></section><section><h3>后端匹配方式</h3><p class="probe-explain">后端按 <code>proxy_id</code> 取 ProxyLease 和凭据版本配置 transport；不会按出口 IP 反查代理，也不会把代理 URL 放进任务请求。</p></section><section><h3>引用渠道 · {{ drawer.refs.length }}</h3><p v-if="!drawer.refs.length" class="muted">暂无渠道引用，可在对应 MCP 渠道设置中绑定。</p><ul v-else><li v-for="reference in drawer.refs" :key="reference">⌁ <span>{{ reference }}</span></li></ul></section><section><h3>审计时间线</h3><p class="event">● 完成 Core 代理探测 · {{ drawer.latency }}<small>今天 14:28 · Yuki Lin</small></p><p class="event">● 创建 ProxyEndpoint<small>2026-09-12 11:06 · Yuki Lin</small></p></section></div></aside>
    <div v-if="modal" class="modal-shade" @click.self="modal = null"><section class="proxy-modal"><header><h2>{{ modal === 'add' ? '添加代理' : modal === 'edit' ? '编辑代理' : modal === 'import' ? '批量导入代理' : '删除代理' }}</h2><button @click="modal = null">×</button></header><form v-if="modal === 'add' || modal === 'edit'" @submit.prevent="save"><div class="form-grid"><label class="full">名称<input v-model="form.name" required placeholder="例如：Google Omni 出口"></label><label>协议<select v-model="form.protocol"><option>HTTP</option><option>HTTPS</option><option>SOCKS5</option><option>SOCKS5H</option></select></label><label>主机<input v-model="form.host" required placeholder="proxy.example.net"></label><label>端口<input v-model="form.port" required type="number" placeholder="8080"></label><label>出口位置<input v-model="form.region" placeholder="美国 · 洛杉矶"></label><p class="secret full">凭据由 Station Secret Store 加密保存。密码只写入，不回显。</p><label>用户名<input v-model="form.username" placeholder="proxy-user"></label><label>密码<input v-model="form.password" type="password" placeholder="输入新密码以轮换"></label><label>有效期<select v-model="form.expiry"><option>长期有效</option><option>30 天后到期</option><option>90 天后到期</option></select></label><label>标签<input v-model="form.tag" placeholder="google, primary"></label><label class="full">备注<textarea v-model="form.note"></textarea></label></div><footer><button type="button" @click="modal = null">取消</button><button class="primary">保存代理</button></footer></form><div v-else-if="modal === 'import'" class="import-body"><label>粘贴代理 URL（每行一条）<textarea v-model="importText" placeholder="http://user:password@proxy.example.net:8080"></textarea></label><p v-if="importPreview" class="preview">{{ importPreview }}</p><footer><button @click="modal = null">取消</button><button @click="parseImport">预览解析</button><button class="primary" @click="confirmImport">确认导入</button></footer></div><div v-else class="delete-body"><p>确定删除 <b>{{ rows.find((row) => row.id === editingId)?.name }}</b> 吗？删除后不能恢复。</p><small>该操作会写入 Station Audit。已引用代理不能直接删除。</small><footer><button @click="modal = null">取消</button><button class="danger" @click="confirmDelete">确认删除</button></footer></div></section></div>
    <transition name="toast"><div v-if="notice" class="toast">{{ notice }}</div></transition>
  </div>
</template>

<style scoped>
.proxy-page{--bg:#090d0b;--surface:#111812;--surface2:#172119;--line:#2b392f;--text:#edf4ee;--muted:#91a096;--green:#63e6a3;--amber:#f4bd68;--red:#ff7980;min-height:100vh;background:var(--bg);color:var(--text);display:grid;grid-template-columns:232px 1fr;font-size:14px}.proxy-page button,.proxy-page input,.proxy-page select,.proxy-page textarea{font:inherit}.proxy-page button{cursor:pointer}.proxy-side{background:#0b100d;border-right:1px solid var(--line);padding:22px 15px;display:flex;flex-direction:column}.proxy-brand{display:flex;align-items:center;gap:10px;color:var(--text);text-decoration:none;padding:2px 10px 28px}.proxy-brand b{display:block;font-size:15px}.proxy-brand small{display:block;color:var(--muted);font-size:10px;letter-spacing:.15em}.proxy-mark{width:27px;height:27px;border:1px solid var(--green);border-radius:50%;display:grid;place-items:center;color:var(--green)}.side-label{color:#66736a;font-size:10px;letter-spacing:.16em;margin:0 10px 8px}.proxy-side nav{display:grid;gap:4px}.proxy-side nav a{color:#aab6ad;text-decoration:none;padding:10px;border-radius:8px;display:flex;gap:10px}.proxy-side nav a.selected,.proxy-side nav a:hover{color:var(--green);background:#63e6a31a}.proxy-user{margin-top:auto;border-top:1px solid var(--line);padding:16px 9px;display:flex;align-items:center;gap:9px}.proxy-user>strong{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#31483a;color:var(--green);font-size:11px}.proxy-user span{font-size:12px}.proxy-user small{display:block;color:var(--muted);font-size:10px}.proxy-main{min-width:0}.proxy-top{height:66px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 32px}.crumb{color:var(--muted);font-size:12px}.crumb i{font-style:normal;margin:0 8px;color:#566258}.crumb b{color:var(--text)}.top-right{display:flex;align-items:center;gap:12px}.top-right select,.top-right button,.toolbar select,.toolbar button,.drawer-actions button,.proxy